 "content": "def transform(grid):
    """Connect same-colored markers lying in the same row or column."""
    from collections import Counter

    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    markers = [v for v, n in counts.items() if v != background]
    if not markers:
        return [row[:] for row in grid]
    marker = markers[0]
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == marker]
        if len(cols) >= 2:
            for c in range(min(cols), max(cols) + 1):
                if out[r][c] == background:
                    out[r][c] = 3
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == marker]
        if len(rows) >= 2:
            for r in range(min(rows), max(rows) + 1):
                if out[r][c] == background:
                    out[r][c] = 3
    return out
